// Single source of truth for the Excel template's raw column headers.
// Every node downstream of this one only ever sees the canonical
// snake_case field names on the left - if the Excel template's column
// headers change, this map is the only thing that needs editing.
const COLUMN_MAP = {
  test_id: 'Test ID',
  description: 'Description',
  steps: 'Steps',
  expected_result: 'Expected Result',
  verification_type: 'Verification Type'
};

const raw = $input.item.json;

// Every test case in a single execution comes from the same triggered
// file, so the source file name can be read once from the trigger node.
const triggerPath = $('Test Script Folder Trigger').first().json.path;
const sourceFile = String(triggerPath).split(/[\\/]/).pop();

const mapped = {};
for (const [canonicalKey, excelHeader] of Object.entries(COLUMN_MAP)) {
  const value = raw[excelHeader];
  mapped[canonicalKey] = (value === undefined || value === null || value === '')
    ? null
    : String(value).trim();
}

// Row metadata is stamped here, before the empty-row filter, so
// row_number always reflects the row's real position in the source
// file even after blank/invalid rows are dropped further downstream.
mapped.__source_file = sourceFile;
mapped.__row_number = $itemIndex + 2; // +2: row 1 is the header row

return { json: mapped };

// Needs visibility across every row in the file at once, so this runs
// once for the whole batch rather than once per item. Flags rows whose
// test_id repeats - a duplicate would silently overwrite itself in the
// Excel report and in the Jira duplicate-ticket lookup later, so it must
// surface as a data-quality error instead.
const items = $input.all();
const counts = {};

for (const item of items) {
  const id = item.json.test_id;
  counts[id] = (counts[id] || 0) + 1;
}

return items.map((item) => ({
  json: {
    ...item.json,
    __duplicate_test_id: counts[item.json.test_id] > 1
  }
}));

// Validates one mapped row and, if valid, builds the shared Test Case
// JSON object (docs/architecture/milestone-1.md, section 7, plus the
// ingestion metadata required by docs/contracts/planner-contract.md).
// Invalid rows return the shared ERROR payload instead
// (docs/contracts/error-payload.md) - they never reach the Planner as a
// test case.
const WORKFLOW_VERSION = '1.0';
const SUPPORTED_VERIFICATION_TYPES = ['api'];

const row = $input.item.json;
const ingestionTimestamp = new Date().toISOString();

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: 'ingestion',
    code,
    message,
    details: details || {},
    timestamp: ingestionTimestamp,
    workflow_version: WORKFLOW_VERSION
  };
}

const requiredFields = ['test_id', 'description', 'steps', 'expected_result', 'verification_type'];
const missing = requiredFields.filter((field) => !row[field]);

if (missing.length > 0) {
  return { json: errorPayload(
    'MISSING_REQUIRED_FIELD',
    `Row ${row.__row_number} in ${row.__source_file} is missing required field(s): ${missing.join(', ')}`,
    { source_file: row.__source_file, row_number: row.__row_number, missing_fields: missing }
  ) };
}

if (!SUPPORTED_VERIFICATION_TYPES.includes(row.verification_type)) {
  return { json: errorPayload(
    'UNSUPPORTED_VERIFICATION_TYPE',
    `Row ${row.__row_number} in ${row.__source_file} has an unsupported verification_type: "${row.verification_type}". Milestone 1 only supports: ${SUPPORTED_VERIFICATION_TYPES.join(', ')}`,
    { source_file: row.__source_file, row_number: row.__row_number, verification_type: row.verification_type }
  ) };
}

if (row.__duplicate_test_id) {
  return { json: errorPayload(
    'DUPLICATE_TEST_ID',
    `Test ID "${row.test_id}" appears more than once in ${row.__source_file}`,
    { source_file: row.__source_file, row_number: row.__row_number, test_id: row.test_id }
  ) };
}

const testCase = {
  test_id: row.test_id,
  description: row.description,
  steps: row.steps,
  expected_result: row.expected_result,
  actual_result: null,
  status: null,
  confidence: null,
  evidence: null,
  next_action: null,
  verification_type: row.verification_type,
  tester: 'AI-Agent',
  date: null,
  notes: null,
  agent_reasoning: null,
  jira_key: null,
  run_id: $execution.id,
  workflow_version: WORKFLOW_VERSION,
  prompt_version: null,
  model_version: null,
  repo_commit: null,
  timestamp: ingestionTimestamp,
  human_verdict: null,
  source_file: row.__source_file,
  row_number: row.__row_number,
  ingestion_timestamp: ingestionTimestamp
};

return { json: testCase };

// Wraps a valid test case in the standard Planner routing contract
// (docs/contracts/planner-contract.md). AGENT_ROUTES is the only place
// that maps a verification_type to a downstream agent/node - adding
// repository/database/ui agents in later milestones means adding a line
// here, not reshaping this workflow or any existing consumer.
const AGENT_ROUTES = {
  api: { agent: 'api', next_node: 'API Agent' }
};
const WORKFLOW_VERSION = '1.0';

const item = $input.item.json;

// ERROR payloads from the previous step are not test cases and must not
// be routed to an agent - pass them through unchanged.
if (item.status === 'ERROR') {
  return { json: item };
}

const route = AGENT_ROUTES[item.verification_type];

if (!route) {
  return { json: {
    status: 'ERROR',
    stage: 'planner_routing',
    code: 'NO_ROUTE_FOR_VERIFICATION_TYPE',
    message: `No agent route configured for verification_type "${item.verification_type}"`,
    details: { test_id: item.test_id, verification_type: item.verification_type },
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  } };
}

return { json: {
  workflow_version: WORKFLOW_VERSION,
  ingestion_timestamp: item.ingestion_timestamp,
  agent: route.agent,
  verification_type: item.verification_type,
  next_node: route.next_node,
  test_case: item
} };
